/**
 * Builds every texture used by the solar-system section.
 *
 *   node scripts/space-assets/build-textures.mjs
 *
 * - Real bodies use Solar System Scope maps (CC BY 4.0, NASA-derived), resized
 *   and renamed, with normal / roughness maps derived from them.
 * - The volcanic and ice worlds are fictional, so they are generated by sampling
 *   3D noise on the unit sphere: every pixel maps to a direction, which makes the
 *   equirectangular maps seamless at the wrap and free of pole pinching.
 * - Selector thumbnails are ray-traced from the same albedo maps.
 * - Hull panel maps for the spacecraft tile seamlessly.
 */
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import sharp from "sharp";
import { createNoise, mix, smoothstep } from "./noise.mjs";

const ROOT = path.resolve("public/assets/space");
const TEX = path.join(ROOT, "textures");
const TEX_1K = path.join(TEX, "1k");
const THUMBS = path.join(ROOT, "thumbs");
const CACHE = path.join(os.tmpdir(), "contenaissance-space-sources");
const SOURCE_URL = "https://www.solarsystemscope.com/textures/download/";

const W = 2048;
const H = 1024;

const report = [];

async function download(file) {
  await fs.mkdir(CACHE, { recursive: true });
  const target = path.join(CACHE, file);
  try {
    return await fs.readFile(target);
  } catch {
    const res = await fetch(SOURCE_URL + file);
    if (!res.ok) throw new Error(`Download failed ${file}: ${res.status}`);
    const buf = Buffer.from(await res.arrayBuffer());
    await fs.writeFile(target, buf);
    return buf;
  }
}

async function loadRaw(file, width = W, height = H, channels = 3) {
  const buf = await download(file);
  let pipe = sharp(buf).resize(width, height, { fit: "fill", kernel: "lanczos3" });
  pipe = channels === 4 ? pipe.ensureAlpha() : pipe.removeAlpha();
  const { data, info } = await pipe.raw().toBuffer({ resolveWithObject: true });
  return { data, w: info.width, h: info.height, c: info.channels };
}

/**
 * Wrap-seam difference divided by the typical difference between neighbouring
 * interior columns. ~1 means the wrap is indistinguishable from any other column.
 */
function seamError(img) {
  const columnDiff = (a, b) => {
    let sum = 0;
    for (let y = 0; y < img.h; y++) {
      for (let k = 0; k < 3; k++) sum += Math.abs(img.data[(y * img.w + a) * img.c + k] - img.data[(y * img.w + b) * img.c + k]);
    }
    return sum / (img.h * 3);
  };
  let interior = 0;
  const probes = 16;
  for (let i = 1; i <= probes; i++) {
    const x = Math.floor((img.w * i) / (probes + 2));
    interior += columnDiff(x, x + 1);
  }
  interior /= probes;
  return columnDiff(img.w - 1, 0) / Math.max(interior, 1e-3);
}

async function save(name, img, { format = "jpg", quality = 88, mobile = true } = {}) {
  const raw = { raw: { width: img.w, height: img.h, channels: img.c } };
  const encode = (pipe) => (format === "png" ? pipe.png({ compressionLevel: 9 }) : pipe.jpeg({ quality, mozjpeg: true }));
  const file = path.join(TEX, name);
  await encode(sharp(img.data, raw)).toFile(file);
  const stat = await fs.stat(file);
  if (mobile) {
    await encode(sharp(img.data, raw).resize(Math.round(img.w / 2), Math.round(img.h / 2), { kernel: "lanczos3" })).toFile(path.join(TEX_1K, name));
  }
  report.push({ file: `textures/${name}`, size: `${img.w}x${img.h}`, kb: Math.round(stat.size / 1024), seam: img.c >= 3 ? seamError(img).toFixed(2) : "-" });
}

function luminance(img) {
  const out = new Float32Array(img.w * img.h);
  for (let i = 0; i < out.length; i++) {
    const o = i * img.c;
    out[i] = (img.data[o] * 0.2126 + img.data[o + 1] * 0.7152 + img.data[o + 2] * 0.0722) / 255;
  }
  return out;
}

function blur(height, w, h, radius) {
  const tmp = new Float32Array(height.length);
  const out = new Float32Array(height.length);
  const n = radius * 2 + 1;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      let s = 0;
      for (let k = -radius; k <= radius; k++) s += height[y * w + ((x + k + w) % w)];
      tmp[y * w + x] = s / n;
    }
  }
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      let s = 0;
      for (let k = -radius; k <= radius; k++) s += tmp[Math.min(h - 1, Math.max(0, y + k)) * w + x];
      out[y * w + x] = s / n;
    }
  }
  return out;
}

/** Tangent-space (OpenGL, +Y up) normal map from a height field; wraps horizontally. */
function normalFromHeight(height, w, h, strength, wrapY = false) {
  const data = Buffer.alloc(w * h * 3);
  for (let y = 0; y < h; y++) {
    const yu = wrapY ? (y - 1 + h) % h : Math.max(0, y - 1);
    const yd = wrapY ? (y + 1) % h : Math.min(h - 1, y + 1);
    for (let x = 0; x < w; x++) {
      const xl = (x - 1 + w) % w;
      const xr = (x + 1) % w;
      const dx = (height[y * w + xr] - height[y * w + xl]) * strength;
      const dy = (height[yd * w + x] - height[yu * w + x]) * strength;
      let nx = -dx;
      let ny = dy;
      let nz = 1;
      const len = Math.hypot(nx, ny, nz);
      nx /= len;
      ny /= len;
      nz /= len;
      const o = (y * w + x) * 3;
      data[o] = Math.round((nx * 0.5 + 0.5) * 255);
      data[o + 1] = Math.round((ny * 0.5 + 0.5) * 255);
      data[o + 2] = Math.round((nz * 0.5 + 0.5) * 255);
    }
  }
  return { data, w, h, c: 3 };
}

function grayImage(values, w, h) {
  const data = Buffer.alloc(w * h * 3);
  for (let i = 0; i < values.length; i++) {
    const v = Math.round(Math.min(1, Math.max(0, values[i])) * 255);
    data[i * 3] = v;
    data[i * 3 + 1] = v;
    data[i * 3 + 2] = v;
  }
  return { data, w, h, c: 3 };
}

function colorImage(rgb, w, h) {
  const data = Buffer.alloc(w * h * 3);
  for (let i = 0; i < rgb.length; i++) {
    // Linear working values → sRGB-encoded bytes.
    const v = Math.min(1, Math.max(0, rgb[i]));
    data[i] = Math.round((v <= 0.0031308 ? v * 12.92 : 1.055 * Math.pow(v, 1 / 2.4) - 0.055) * 255);
  }
  return { data, w, h, c: 3 };
}

/** Calls fn(dx, dy, dz, index) for every texel of an equirectangular map. */
function eachDirection(w, h, fn) {
  for (let y = 0; y < h; y++) {
    const lat = (0.5 - (y + 0.5) / h) * Math.PI;
    const cl = Math.cos(lat);
    const sl = Math.sin(lat);
    for (let x = 0; x < w; x++) {
      const lon = ((x + 0.5) / w) * Math.PI * 2;
      fn(Math.cos(lon) * cl, sl, Math.sin(lon) * cl, y * w + x);
    }
  }
}

// ---------------------------------------------------------------------------
// Fictional worlds
// ---------------------------------------------------------------------------

function buildVolcanic() {
  const { fbm, worley } = createNoise(4242);
  const cell = [0, 0];
  const fine = [0, 0];
  const albedo = new Float32Array(W * H * 3);
  const emissive = new Float32Array(W * H * 3);
  const height = new Float32Array(W * H);
  const rough = new Float32Array(W * H);

  eachDirection(W, H, (x, y, z, i) => {
    const wx = fbm(x * 1.6 + 3, y * 1.6, z * 1.6, 4) - 0.5;
    const wy = fbm(x * 1.6, y * 1.6 + 7, z * 1.6, 4) - 0.5;
    const wz = fbm(x * 1.6, y * 1.6, z * 1.6 + 11, 4) - 0.5;
    const px = x * 3.4 + wx * 0.9;
    const py = y * 3.4 + wy * 0.9;
    const pz = z * 3.4 + wz * 0.9;
    worley(px, py, pz, cell);
    worley(px * 3.1, py * 3.1, pz * 3.1, fine);
    const edge = cell[1] - cell[0];
    const fineEdge = fine[1] - fine[0];
    const heat = fbm(x * 1.2 + 40, y * 1.2, z * 1.2, 4);
    const rock = fbm(x * 7, y * 7, z * 7, 6);
    const grit = fbm(x * 26, y * 26, z * 26, 3);

    const major = 1 - smoothstep(0.0, 0.028 + heat * 0.03, edge);
    const minor = (1 - smoothstep(0.0, 0.022, fineEdge)) * smoothstep(0.5, 0.8, heat) * 0.5;
    const crack = Math.min(1, major + minor * (1 - major));
    const glow = Math.pow(crack, 2.2) * mix(0.22, 1.0, smoothstep(0.35, 0.8, heat));

    let r = mix(0.028, 0.085, rock);
    let g = mix(0.024, 0.07, rock);
    let b = mix(0.022, 0.062, rock);
    const ash = smoothstep(0.62, 0.85, rock) * 0.5;
    r = mix(r, 0.16, ash);
    g = mix(g, 0.14, ash);
    b = mix(b, 0.13, ash);
    r *= 0.8 + grit * 0.4;
    g *= 0.8 + grit * 0.4;
    b *= 0.8 + grit * 0.4;
    r = mix(r, 0.22, crack * 0.5);
    g = mix(g, 0.07, crack * 0.5);
    b = mix(b, 0.02, crack * 0.5);

    albedo[i * 3] = r;
    albedo[i * 3 + 1] = g;
    albedo[i * 3 + 2] = b;

    const core = smoothstep(0.55, 1.0, glow);
    emissive[i * 3] = glow * 0.95;
    emissive[i * 3 + 1] = glow * mix(0.36, 0.7, core);
    emissive[i * 3 + 2] = glow * mix(0.04, 0.24, core);

    height[i] = 0.55 + (rock - 0.5) * 0.5 + grit * 0.08 - crack * 0.5;
    rough[i] = mix(0.86, 0.38, crack) - ash * 0.1;
  });

  return { albedo, emissive, height, rough };
}

function buildIce() {
  const { fbm, worley } = createNoise(913);
  const cell = [0, 0];
  const albedo = new Float32Array(W * H * 3);
  const height = new Float32Array(W * H);
  const rough = new Float32Array(W * H);

  eachDirection(W, H, (x, y, z, i) => {
    const base = fbm(x * 2.2, y * 2.2, z * 2.2, 6);
    const detail = fbm(x * 11, y * 11, z * 11, 4);
    const tint = fbm(x * 1.3 + 9, y * 1.3, z * 1.3, 4);
    const wx = fbm(x * 2 + 5, y * 2, z * 2, 3) - 0.5;
    worley(x * 4.2 + wx, y * 4.2, z * 4.2 - wx, cell);
    const crack = 1 - smoothstep(0.0, 0.035, cell[1] - cell[0]);
    const lineae = 1 - smoothstep(0.0, 0.025, Math.abs(fbm(x * 3, y * 3 + 20, z * 3, 5) - 0.5));
    const polar = smoothstep(0.55, 0.92, Math.abs(y));

    let r = mix(0.36, 0.72, base);
    let g = mix(0.44, 0.78, base);
    let b = mix(0.55, 0.86, base);
    const lav = smoothstep(0.55, 0.75, tint) * 0.45;
    r = mix(r, 0.56, lav);
    g = mix(g, 0.5, lav);
    b = mix(b, 0.72, lav);
    r = mix(r, 0.88, polar * 0.7);
    g = mix(g, 0.91, polar * 0.7);
    b = mix(b, 0.95, polar * 0.7);
    const line = Math.max(crack, lineae * 0.8);
    r = mix(r, 0.2, line * 0.6);
    g = mix(g, 0.3, line * 0.6);
    b = mix(b, 0.46, line * 0.6);
    r *= 0.9 + detail * 0.2;
    g *= 0.9 + detail * 0.2;
    b *= 0.9 + detail * 0.2;

    albedo[i * 3] = r;
    albedo[i * 3 + 1] = g;
    albedo[i * 3 + 2] = b;
    height[i] = base * 0.5 + detail * 0.25 - line * 0.35;
    rough[i] = mix(0.3, 0.7, detail) + line * 0.15 - polar * 0.1;
  });

  return { albedo, height, rough };
}

// ---------------------------------------------------------------------------
// Spacecraft hull panels (tiling)
// ---------------------------------------------------------------------------

function buildHullPanels(size = 1024) {
  const { rand, fbm } = createNoise(77);
  const height = new Float32Array(size * size).fill(1);
  const albedo = new Float32Array(size * size * 3);
  const rough = new Float32Array(size * size);
  const tint = new Float32Array(size * size);

  const rects = [];
  const split = (x, y, w, h, depth) => {
    if (depth > 4 || (depth > 1 && rand() < 0.18) || w < 90 || h < 90) {
      rects.push([x, y, w, h, rand()]);
      return;
    }
    if (w > h * (0.7 + rand() * 0.6)) {
      const cut = Math.round(w * (0.3 + rand() * 0.4));
      split(x, y, cut, h, depth + 1);
      split(x + cut, y, w - cut, h, depth + 1);
    } else {
      const cut = Math.round(h * (0.3 + rand() * 0.4));
      split(x, y, w, cut, depth + 1);
      split(x, y + cut, w, h - cut, depth + 1);
    }
  };
  split(0, 0, size, size, 0);

  const seam = 3;
  for (const [rx, ry, rw, rh, t] of rects) {
    for (let y = ry; y < ry + rh; y++) {
      for (let x = rx; x < rx + rw; x++) {
        const d = Math.min(x - rx, rx + rw - 1 - x, y - ry, ry + rh - 1 - y);
        const i = y * size + x;
        height[i] = d < seam ? 0.25 + (d / seam) * 0.25 : Math.min(1, 0.5 + (d - seam) * 0.12);
        tint[i] = t;
      }
    }
    // Rivet rows along the long edges of larger panels.
    if (rw > 160 && t > 0.45) {
      for (let x = rx + 14; x < rx + rw - 14; x += 22) {
        for (const yy of [ry + 9, ry + rh - 10]) {
          for (let oy = -2; oy <= 2; oy++) {
            for (let ox = -2; ox <= 2; ox++) {
              if (ox * ox + oy * oy > 5) continue;
              const i = ((yy + oy + size) % size) * size + ((x + ox + size) % size);
              height[i] = 1.12;
            }
          }
        }
      }
    }
  }

  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const i = y * size + x;
      const u = x / size;
      const v = y / size;
      // Periodic noise: sample on a torus so the tile wraps.
      const a = u * Math.PI * 2;
      const b = v * Math.PI * 2;
      const n = fbm(Math.cos(a) * 3, Math.sin(a) * 3, Math.cos(b) * 3 + Math.sin(b) * 1.7, 4);
      const grime = fbm(Math.cos(a) * 9, Math.sin(a) * 9 + Math.cos(b) * 9, Math.sin(b) * 9, 3);
      const t = tint[i];
      const seamDark = height[i] < 0.5 ? 0.45 : 1;
      const base = (0.075 + t * 0.03 + (n - 0.5) * 0.02) * seamDark * (0.92 + grime * 0.16);
      albedo[i * 3] = base;
      albedo[i * 3 + 1] = base * 1.02;
      albedo[i * 3 + 2] = base * 1.1;
      rough[i] = (height[i] < 0.5 ? 0.62 : 0.3 + t * 0.12) + (grime - 0.5) * 0.12;
    }
  }

  return { height, albedo, rough, size };
}

function buildBrushedGold(size = 512) {
  const { fbm } = createNoise(31);
  const rough = new Float32Array(size * size);
  for (let y = 0; y < size; y++) {
    const b = (y / size) * Math.PI * 2;
    for (let x = 0; x < size; x++) {
      const a = (x / size) * Math.PI * 2;
      const streak = fbm(Math.cos(a) * 0.6, Math.sin(a) * 0.6, Math.cos(b) * 40 + Math.sin(b) * 40, 4);
      const blotch = fbm(Math.cos(a) * 3, Math.sin(a) * 3, Math.cos(b) * 3 + 5, 3);
      rough[y * size + x] = 0.16 + streak * 0.18 + (blotch - 0.5) * 0.08;
    }
  }
  return rough;
}

// ---------------------------------------------------------------------------
// Thumbnails (orthographic ray-traced spheres)
// ---------------------------------------------------------------------------

function sample(img, u, v) {
  u = ((u % 1) + 1) % 1;
  v = Math.min(1, Math.max(0, v));
  const fx = u * img.w - 0.5;
  const fy = v * (img.h - 1);
  const x0 = Math.floor(fx);
  const y0 = Math.floor(fy);
  const tx = fx - x0;
  const ty = fy - y0;
  const out = [0, 0, 0, 0];
  for (let k = 0; k < img.c; k++) {
    const at = (x, y) => img.data[(Math.min(img.h - 1, y) * img.w + ((x + img.w) % img.w)) * img.c + k];
    const top = mix(at(x0, y0), at(x0 + 1, y0), tx);
    const bot = mix(at(x0, y0 + 1), at(x0 + 1, y0 + 1), tx);
    out[k] = mix(top, bot, ty) / 255;
  }
  if (img.c === 3) out[3] = 1;
  return out;
}

const toLinear = (c) => (c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4));
const toSrgb = (c) => {
  c = Math.min(1, Math.max(0, c));
  return c <= 0.0031308 ? c * 12.92 : 1.055 * Math.pow(c, 1 / 2.4) - 0.055;
};

function renderThumb({ albedo, emissive, clouds, ring, atmosphere, spin = 0, size = 200 }) {
  const data = Buffer.alloc(size * size * 4);
  const radius = ring ? size * 0.235 : size * 0.4;
  const c = size / 2;
  const L = (() => {
    const v = [-0.72, 0.32, 0.62];
    const l = Math.hypot(...v);
    return v.map((x) => x / l);
  })();
  const tilt = 0.32;
  const ct = Math.cos(tilt);
  const st = Math.sin(tilt);
  const ringN = (() => {
    const n = [Math.sin(-0.18), Math.cos(0.42), Math.sin(0.42)];
    const l = Math.hypot(...n);
    return n.map((x) => x / l);
  })();
  const ss = 3;

  for (let py = 0; py < size; py++) {
    for (let px = 0; px < size; px++) {
      let r = 0;
      let g = 0;
      let b = 0;
      let a = 0;
      for (let sy = 0; sy < ss; sy++) {
        for (let sx = 0; sx < ss; sx++) {
          const x = (px + (sx + 0.5) / ss - c) / radius;
          const y = -(py + (sy + 0.5) / ss - c) / radius;
          const d2 = x * x + y * y;
          let col = null;
          let alpha = 0;
          let sphereZ = -Infinity;

          if (d2 <= 1) {
            const z = Math.sqrt(1 - d2);
            sphereZ = z;
            // Undo axial tilt, then spin.
            const tx = x * ct + y * st;
            const ty = -x * st + y * ct;
            const lon = Math.atan2(tx, z) + spin;
            const lat = Math.asin(Math.max(-1, Math.min(1, ty)));
            const u = lon / (Math.PI * 2) + 0.5;
            const v = 0.5 - lat / Math.PI;
            const s = sample(albedo, u, v);
            let cr = toLinear(s[0]);
            let cg = toLinear(s[1]);
            let cb = toLinear(s[2]);
            if (clouds) {
              const cl = sample(clouds, u, v)[0];
              cr = mix(cr, 0.9, cl * 0.85);
              cg = mix(cg, 0.92, cl * 0.85);
              cb = mix(cb, 0.95, cl * 0.85);
            }
            const ndl = x * L[0] + y * L[1] + z * L[2];
            const lit = Math.max(0, ndl) * 1.25 + 0.025;
            cr *= lit;
            cg *= lit;
            cb *= lit;
            if (emissive) {
              const e = sample(emissive, u, v);
              cr += toLinear(e[0]) * 1.3;
              cg += toLinear(e[1]) * 1.3;
              cb += toLinear(e[2]) * 1.3;
            }
            if (atmosphere) {
              const fres = Math.pow(1 - z, 2.6) * (0.35 + Math.max(0, ndl + 0.3));
              cr += atmosphere[0] * fres;
              cg += atmosphere[1] * fres;
              cb += atmosphere[2] * fres;
            }
            col = [cr, cg, cb];
            alpha = 1;
          }

          if (ring) {
            const t = -(x * ringN[0] + y * ringN[1]) / ringN[2];
            const rr = Math.hypot(x, y, t);
            if (rr > 1.25 && rr < 2.05 && (t > sphereZ || d2 > 1)) {
              const s = sample(ring, (rr - 1.25) / 0.8, 0.5);
              const ra = s[3] * 0.92;
              const shade = 0.75;
              const rc = [toLinear(s[0]) * shade, toLinear(s[1]) * shade, toLinear(s[2]) * shade];
              if (col) {
                col = col.map((v, k) => mix(v, rc[k], ra));
              } else {
                col = rc;
                alpha = ra;
              }
            }
          }

          if (col) {
            r += toSrgb(col[0]) * alpha;
            g += toSrgb(col[1]) * alpha;
            b += toSrgb(col[2]) * alpha;
            a += alpha;
          }
        }
      }
      const n = ss * ss;
      const o = (py * size + px) * 4;
      const al = a / n;
      data[o] = al > 0 ? Math.round((r / a) * 255) : 0;
      data[o + 1] = al > 0 ? Math.round((g / a) * 255) : 0;
      data[o + 2] = al > 0 ? Math.round((b / a) * 255) : 0;
      data[o + 3] = Math.round(al * 255);
    }
  }
  return { data, w: size, h: size, c: 4 };
}

async function saveThumb(name, img) {
  const file = path.join(THUMBS, name);
  await sharp(img.data, { raw: { width: img.w, height: img.h, channels: 4 } }).webp({ quality: 90, alphaQuality: 100 }).toFile(file);
  const stat = await fs.stat(file);
  report.push({ file: `thumbs/${name}`, size: `${img.w}x${img.h}`, kb: Math.round(stat.size / 1024), seam: "-" });
}

// ---------------------------------------------------------------------------

async function main() {
  await fs.mkdir(TEX_1K, { recursive: true });
  await fs.mkdir(THUMBS, { recursive: true });

  console.log("Fetching source maps…");
  const sun = await loadRaw("2k_sun.jpg");
  const earth = await loadRaw("2k_earth_daymap.jpg");
  const clouds = await loadRaw("2k_earth_clouds.jpg");
  const mars = await loadRaw("2k_mars.jpg");
  const jupiter = await loadRaw("2k_jupiter.jpg");
  const saturn = await loadRaw("2k_saturn.jpg");
  const moon = await loadRaw("2k_moon.jpg");
  const ring = await loadRaw("2k_saturn_ring_alpha.png", 1024, 64, 4);
  const stars = await loadRaw("8k_stars_milky_way.jpg", 4096, 2048);

  await save("sun-surface.jpg", sun);
  await save("earth-albedo.jpg", earth);
  await save("earth-clouds.jpg", clouds, { quality: 85 });
  await save("mars-albedo.jpg", mars);
  await save("gas-giant-albedo.jpg", jupiter);
  await save("ringed-planet-albedo.jpg", saturn);
  await save("rocky-planet-albedo.jpg", moon);
  await save("planet-ring.png", ring, { format: "png", mobile: false });
  await save("milky-way.jpg", stars, { quality: 84 });

  console.log("Deriving relief and roughness…");
  {
    const lum = luminance(earth);
    const height = new Float32Array(lum.length);
    const rough = new Float32Array(lum.length);
    for (let i = 0; i < lum.length; i++) {
      const o = i * 3;
      const ocean = earth.data[o + 2] > earth.data[o] * 1.15 && earth.data[o + 2] > earth.data[o + 1] * 0.95 ? 1 : 0;
      height[i] = ocean ? 0 : 0.2 + lum[i];
      rough[i] = ocean ? 0.32 : 0.88 - lum[i] * 0.2;
    }
    const soft = blur(height, W, H, 1);
    await save("earth-normal.jpg", normalFromHeight(soft, W, H, 6), { quality: 92 });
    await save("earth-roughness.jpg", grayImage(blur(rough, W, H, 1), W, H));
  }
  for (const [name, img, strength] of [
    ["mars", mars, 9],
    ["rocky-planet", moon, 7],
  ]) {
    const lum = luminance(img);
    const detail = blur(lum, W, H, 1);
    await save(`${name}-normal.jpg`, normalFromHeight(detail, W, H, strength), { quality: 92 });
    const rough = new Float32Array(lum.length);
    for (let i = 0; i < lum.length; i++) rough[i] = 0.78 + (0.5 - lum[i]) * 0.25;
    await save(`${name}-roughness.jpg`, grayImage(rough, W, H));
  }

  console.log("Generating volcanic world…");
  const volcanic = buildVolcanic();
  const volcanicAlbedo = colorImage(volcanic.albedo, W, H);
  const volcanicEmissive = colorImage(volcanic.emissive, W, H);
  await save("volcanic-planet-albedo.jpg", volcanicAlbedo);
  await save("volcanic-planet-emissive.jpg", volcanicEmissive);
  await save("volcanic-planet-normal.jpg", normalFromHeight(blur(volcanic.height, W, H, 1), W, H, 7), { quality: 92 });
  await save("volcanic-planet-roughness.jpg", grayImage(volcanic.rough, W, H));

  console.log("Generating ice world…");
  const ice = buildIce();
  const iceAlbedo = colorImage(ice.albedo, W, H);
  await save("ice-planet-albedo.jpg", iceAlbedo);
  await save("ice-planet-normal.jpg", normalFromHeight(blur(ice.height, W, H, 1), W, H, 5), { quality: 92 });
  await save("ice-planet-roughness.jpg", grayImage(ice.rough, W, H));

  console.log("Generating hull panels…");
  const hull = buildHullPanels();
  await save("ship-hull-albedo.jpg", colorImage(hull.albedo, hull.size, hull.size), { mobile: false });
  await save("ship-hull-normal.jpg", normalFromHeight(hull.height, hull.size, hull.size, 3, true), { quality: 92, mobile: false });
  await save("ship-hull-roughness.jpg", grayImage(hull.rough, hull.size, hull.size), { mobile: false });
  await save("ship-gold-roughness.jpg", grayImage(buildBrushedGold(), 512, 512), { mobile: false });

  console.log("Rendering thumbnails…");
  await saveThumb("mars.webp", renderThumb({ albedo: mars, atmosphere: [0.35, 0.16, 0.08], spin: 1.2 }));
  await saveThumb("earth.webp", renderThumb({ albedo: earth, clouds, atmosphere: [0.25, 0.5, 0.95], spin: 2.2 }));
  await saveThumb("ringed.webp", renderThumb({ albedo: saturn, ring, atmosphere: [0.5, 0.4, 0.25] }));
  await saveThumb("volcanic.webp", renderThumb({ albedo: volcanicAlbedo, emissive: volcanicEmissive, atmosphere: [0.9, 0.5, 0.15], spin: 0.6 }));
  await saveThumb("ice.webp", renderThumb({ albedo: iceAlbedo, atmosphere: [0.45, 0.6, 0.9], spin: 0.4 }));
  await saveThumb("rocky.webp", renderThumb({ albedo: moon, spin: 0.9 }));
  await saveThumb("gas-giant.webp", renderThumb({ albedo: jupiter, ring, atmosphere: [0.5, 0.4, 0.28], spin: 0.3 }));

  console.table(report);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
